package com.corecs.solid.rules;import com.corecs.solid.model.*;import java.util.*;public class LspRule implements SolidRule{public List<Issue> analyze(List<ClassInfo> cs){List<Issue> o=new ArrayList<>();for(var c:cs)if(c.parent()!=null&&!c.overriddenMethods().isEmpty())o.add(new Issue("LSP","Review",c.name(),"Inheritance with overrides needs substitutability review","Overriding methods is not a violation by itself; the key question is whether the subtype preserves the parent contract.","Check preconditions, postconditions, invariants, and exception behavior."));return o;}}
